// Aggregate a potentially HUGE csv in chunks so the LLM never sees raw rows.
// Analyzes up to MAX_ROWS rows (sample of a big file) - per-column stats + missing values.
const MAX_ROWS = 100000;

const items = $input.all();
const firstBinary = items[0].binary || {};
const binKey = Object.keys(firstBinary)[0];
if (!binKey) throw new Error('No binary file found. Check the Unzip node output.');

const buffer = await this.helpers.getBinaryDataBuffer(0, binKey);
let text = buffer.toString('utf8');

// strip UTF-8 BOM
if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);

const lines = text.split(/\r?\n/);
const header = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));
const nCols = header.length;

const stats = header.map(name => ({
  name, count: 0, missing: 0, numericCount: 0, sum: 0, sumSq: 0,
  min: Infinity, max: -Infinity, uniques: new Set(), isNumeric: true
}));

let rowsAnalyzed = 0;
for (let i = 1; i < lines.length && rowsAnalyzed < MAX_ROWS; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const cells = line.split(',');
  rowsAnalyzed++;
  for (let c = 0; c < nCols; c++) {
    const s = (cells[c] ?? '').trim().replace(/^"|"$/g, '');
    const st = stats[c];
    if (s === '' || s.toLowerCase() === 'na' || s.toLowerCase() === 'null') { st.missing++; continue; }
    st.count++;
    if (st.uniques.size < 1000) st.uniques.add(s);
    const v = Number(s);
    if (!Number.isNaN(v) && st.isNumeric) {
      st.numericCount++; st.sum += v; st.sumSq += v * v;
      if (v < st.min) st.min = v;
      if (v > st.max) st.max = v;
    } else if (Number.isNaN(v)) {
      // only flip to categorical if a non-numeric value appears after numeric ones or early on
      if (st.numericCount < st.count) st.isNumeric = false;
    }
  }
}

const columns = stats.map(st => {
  const base = {
    name: st.name,
    analyzed_non_missing: st.count,
    missing: st.missing,
    unique_values: st.uniques.size,
    type: st.isNumeric && st.numericCount > 0 ? 'numeric' : 'categorical/text'
  };
  if (base.type === 'numeric' && st.numericCount > 0) {
    const mean = st.sum / st.numericCount;
    const variance = Math.max(0, st.sumSq / st.numericCount - mean * mean);
    base.mean = +mean.toFixed(4);
    base.std = +Math.sqrt(variance).toFixed(4);
    base.min = +st.min.toFixed(4);
    base.max = +st.max.toFixed(4);
  } else {
    base.top_values = [...st.uniques].slice(0, 5);
  }
  return base;
});

return [{ json: {
  source: 'Kaggle Insight Pipeline',
  total_rows_in_file: lines.length - 1,
  rows_analyzed: rowsAnalyzed,
  sampled: rowsAnalyzed < (lines.length - 1),
  column_count: nCols,
  columns
}}];

// Shape the Insight Writer Agent output for the Google Sheets node
const out = $input.first().json;
const text = out.output || out.text || JSON.stringify(out);
return [{ json: { insight_text: String(text).slice(0, 4000) } }];
